  <main>
    <section class="support-card" aria-labelledby="support-title">
      <div class="hero">
        <p class="eyebrow">Support</p>
        <h1 id="support-title">How can we help?</h1>
        <p class="intro">Send our team your contact details and we will follow up with support options for your account.</p>
      </div>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            required
            aria-required="true"
            aria-describedby="full-name-error"
          >
          <p class="error-message" id="full-name-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="email">Email address <span class="required" aria-hidden="true">*</span></label>
          <input
            id="email"
            name="email"
            type="email"
            autocomplete="email"
            required
            aria-required="true"
            aria-describedby="email-error"
          >
          <p class="error-message" id="email-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="phone">Phone number</label>
          <input
            id="phone"
            name="phone"
            type="tel"
            autocomplete="tel"
            inputmode="tel"
            aria-describedby="phone-helper phone-error"
          >
          <p class="helper-text" id="phone-helper">Optional. Use 10 to 15 digits, with spaces, hyphens, parentheses, or a leading plus sign if needed.</p>
          <p class="error-message" id="phone-error" aria-live="polite"></p>
        </div>

        <button type="submit">Contact support</button>
        <p class="form-status" id="form-status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#support-form");
    const fields = {
      fullName: document.querySelector("#full-name"),
      email: document.querySelector("#email"),
      phone: document.querySelector("#phone")
    };
    const errors = {
      fullName: document.querySelector("#full-name-error"),
      email: document.querySelector("#email-error"),
      phone: document.querySelector("#phone-error")
    };
    const formStatus = document.querySelector("#form-status");

    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const phoneAllowedPattern = /^\+?[0-9\s\-()]*$/;

    function setError(fieldName, message) {
      const field = fields[fieldName];
      const error = errors[fieldName];

      field.setAttribute("aria-invalid", message ? "true" : "false");
      error.textContent = message;
    }

    function validateField(fieldName) {
      const value = fields[fieldName].value.trim();

      if (fieldName === "fullName") {
        if (!value) {
          setError(fieldName, "Enter your full name.");
          return false;
        }
      }

      if (fieldName === "email") {
        if (!value) {
          setError(fieldName, "Enter your email address.");
          return false;
        }

        if (!emailPattern.test(value)) {
          setError(fieldName, "Enter a valid email address, such as name@example.com.");
          return false;
        }
      }

      if (fieldName === "phone" && value) {
        const digits = value.replace(/\D/g, "");

        if (!phoneAllowedPattern.test(value) || digits.length < 10 || digits.length > 15) {
          setError(fieldName, "Enter a phone number with 10 to 15 digits, using only spaces, hyphens, parentheses, or a leading plus sign.");
          return false;
        }
      }

      setError(fieldName, "");
      return true;
    }

    function validateForm() {
      const fieldNames = Object.keys(fields);
      const results = fieldNames.map(validateField);
      return results.every(Boolean);
    }

    Object.keys(fields).forEach((fieldName) => {
      fields[fieldName].addEventListener("blur", () => {
        validateField(fieldName);
      });

      fields[fieldName].addEventListener("input", () => {
        formStatus.textContent = "";

        if (fields[fieldName].getAttribute("aria-invalid") === "true") {
          validateField(fieldName);
        }
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!validateForm()) {
        const firstInvalidField = Object.values(fields).find((field) => field.getAttribute("aria-invalid") === "true");
        firstInvalidField.focus();
        formStatus.textContent = "";
        return;
      }

      form.reset();
      Object.keys(fields).forEach((fieldName) => setError(fieldName, ""));
      formStatus.textContent = "Thanks. Your support request contact details were submitted.";
    });
  </script>
