 <body>
   <main>
     <section class="support-card" aria-labelledby="support-title">
       <div class="hero">
         <p class="eyebrow">Support</p>
         <h1 id="support-title">How can we help?</h1>
         <p class="intro">Send our team your contact details and we will follow up with support options for your account.</p>
       </div>

       <form id="support-form" novalidate>
         <div class="form-field">
           <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
           <input
             id="full-name"
             name="fullName"
             type="text"
             autocomplete="name"
             required
             aria-required="true"
             aria-describedby="full-name-error"
           >
           <p class="error-message" id="full-name-error" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="email">Email address <span class="required" aria-hidden="true">*</span></label>
           <input
             id="email"
             name="email"
             type="email"
             autocomplete="email"
             required
             aria-required="true"
             aria-describedby="email-error"
           >
           <p class="error-message" id="email-error" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="phone">Phone number</label>
           <input
             id="phone"
             name="phone"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             aria-describedby="phone-helper phone-error"
           >
           <p class="helper-text" id="phone-helper">Optional. Use 10 to 15 digits, with spaces, hyphens, parentheses, or a leading plus sign if needed.</p>
           <p class="error-message" id="phone-error" aria-live="polite"></p>
         </div>

         <button type="submit">Contact support</button>
         <p class="form-status" id="form-status" aria-live="polite"></p>
       </form>
     </section>
   </main>

